(() => {
'use strict';
const data=window.ATLAS_KNOWLEDGE_TREE;
const $=s=>document.querySelector(s);
const el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};
const copy=(zh,en,ja,ko)=>({zh,en,ja,ko});
const words={tab:copy('知识树','Knowledge tree','知識ツリー','지식 트리'),search:copy('搜索概念、区别或案例…','Search concepts, distinctions or examples…','概念・違い・事例を検索…','개념, 차이, 사례 검색…'),clear:copy('清空','Clear','クリア','지우기'),expand:copy('展开全部','Expand all','すべて展開','모두 펼치기'),collapse:copy('收起全部','Collapse all','すべて閉じる','모두 접기'),download:copy('导出学习树 ↓','Export study tree ↓','学習ツリーを出力 ↓','학습 트리 내보내기 ↓'),empty:copy('没有匹配的概念。换个词，或清空搜索。','No matching concepts. Try another term or clear the search.','該当する概念がありません。別の語を試してください。','일치하는 개념이 없습니다. 다른 용어를 검색해 보세요.'),definition:copy('定义','Definition','定義','정의'),distinction:copy('别混淆','Distinction','区別','구분'),example:copy('案例 / 思考实验','Case / thought experiment','事例・思考実験','사례 / 사고실험'),prompt:copy('练一题','Practice','練習','연습'),refs:copy('沿原典继续读','Follow the primary texts','原典へ進む','원전으로 이어 읽기'),roadmap:copy('三轮学习路线','Three reading rounds','三段階の学習','세 단계 학습'),comparison:copy('横向对照','Comparisons','比較','비교'),notes:copy('概念练习','Concept practice','概念の練習','개념 연습'),review:copy('头像核查','Portrait review','肖像の確認','초상 검토'),license:copy('许可条款 ↗','License terms ↗','利用条件 ↗','이용조건 ↗')};
const lang=()=>document.documentElement.lang==='zh-CN'?'zh':document.documentElement.lang;
const L=c=>c[lang()]||c.en||c.zh;
function local(e,c){e.dataset.noTranslate='true';e.textContent=L(c);return e}
function link(label,url){const e=el('a','',label);e.href=url;e.target='_blank';e.rel='noopener noreferrer';return e}
function sourceButtons(refs){const wrap=el('div','tree-sources');for(const id of refs){const n=window.ATLAS.nodes.find(n=>n.id===id);if(!n)continue;const b=el('button','',n.name);b.type='button';b.onclick=()=>{$('header [data-view="atlas"]').click();window.ATLAS_APP.jumpTo(id)};const source=link('↗',n.url);source.setAttribute('aria-label',n.name+' · '+n.book);wrap.append(b,source);}return wrap}
const view=el('section','knowledge-tree-page');view.id='treeView';view.hidden=true;view.dataset.noTranslate='true';$('main').insertBefore(view,$('.site-foot'));
const tab=el('button','tab');tab.dataset.view='tree';tab.dataset.noTranslate='true';$('header nav').insertBefore(tab,$('header [data-view="profile"]'));
tab.onclick=()=>{document.querySelectorAll('main>section[id$="View"]').forEach(e=>e.hidden=e!==view);document.querySelectorAll('.tab').forEach(b=>{b.classList.toggle('active',b===tab);b.setAttribute('aria-pressed',String(b===tab))});window.scrollTo({top:0,behavior:'auto'})};
const head=el('div','tree-heading');head.append(el('p','eyebrow','POLITICAL FOUNDATIONS / ALKAID’S STUDY NOTES'),el('h1','',data.title),el('p','tree-lead','先把问题分清，再沿文献往下走。'),el('p','tree-origin',data.origin));view.append(head);
const controls=el('div','tree-controls'),input=el('input','tree-search');input.type='search';const clear=el('button'),expand=el('button'),collapse=el('button'),download=el('button');controls.append(input,clear,expand,collapse,download);view.append(controls);
const count=el('p','tree-count');count.setAttribute('aria-live','polite');view.append(count);
const layout=el('div','tree-layout'),nav=el('nav','tree-navigation'),content=el('div','tree-content');nav.setAttribute('aria-label','知识树问题导航');layout.append(nav,content);view.append(layout);
const empty=el('p','tree-empty');empty.hidden=true;content.append(empty);
const groups=[];
for(const group of data.groups){
 const anchor=el('a','',group.title);anchor.href='#tree-'+group.id;nav.append(anchor);
 const section=el('section','tree-group');section.id='tree-'+group.id;section.append(el('h2','',group.title),el('p','tree-question',group.question));
 const items=[];
 for(const item of group.items){
  const details=el('details','tree-concept');details.open=group.id==='politics';
  const summary=el('summary'),label=el('strong','',item.term),english=el('span','tree-english',item.en);summary.append(label,english);details.append(summary);
  const body=el('div','tree-concept-body');
  for(const key of ['definition','distinction','example','prompt']){const block=el('div','tree-'+key);block.append(local(el('h3'),words[key]),el('p','',item[key]));body.append(block)}
  body.append(local(el('h3'),words.refs),sourceButtons(item.refs));details.append(body);section.append(details);
  items.push({item,details,text:[item.term,item.en,item.definition,item.distinction,item.example,item.prompt,...item.refs.map(id=>window.ATLAS.nodes.find(n=>n.id===id)?.name||'')].join(' ').toLocaleLowerCase()});
 }
 content.append(section);groups.push({group,section,anchor,items});
}
const comparison=el('section','tree-comparisons');comparison.append(local(el('h2'),words.comparison));
for(const c of data.comparisons){const tableWrap=el('div','tree-table-scroll'),table=el('table'),caption=el('caption','',c.title),thead=el('thead'),tr=el('tr');for(const h of c.headers){const th=el('th','',h);th.scope='col';tr.append(th)}thead.append(tr);const tbody=el('tbody');for(const row of c.rows){const r=el('tr');row.forEach((v,i)=>{const cell=el(i===0?'th':'td','',v);if(i===0)cell.scope='row';r.append(cell)});tbody.append(r)}table.append(caption,thead,tbody);tableWrap.append(table);comparison.append(tableWrap,sourceButtons(c.refs))}content.append(comparison);
const route=el('section','tree-route');route.append(local(el('h2'),words.roadmap));for(const r of data.route){const box=el('article');box.append(el('h3','',r.title),el('p','',r.text));const links=el('div','tree-sources');for(const id of r.groups){const g=data.groups.find(x=>x.id===id);const a=el('a','',g.title);a.href='#tree-'+id;links.append(a)}box.append(links);route.append(box)}content.append(route);
function filter(){const q=input.value.trim().toLocaleLowerCase();let total=0;for(const g of groups){let matches=0;for(const item of g.items){const match=!q||item.text.includes(q)||g.group.title.toLocaleLowerCase().includes(q);item.details.hidden=!match;if(q&&match)item.details.open=true;if(match)matches++}g.section.hidden=!matches;g.anchor.hidden=!matches;total+=matches}empty.hidden=total!==0;count.textContent=total+' / '+data.groups.reduce((n,g)=>n+g.items.length,0)+' '+L(copy('个概念 · '+data.groups.length+'个问题分支','concepts · '+data.groups.length+' question branches', '概念・'+data.groups.length+'問の分岐', '개념 · '+data.groups.length+'개 질문 분기'));comparison.hidden=!!q;route.hidden=!!q;}
input.addEventListener('input',filter);clear.onclick=()=>{input.value='';filter();input.focus()};expand.onclick=()=>groups.forEach(g=>g.items.forEach(i=>{if(!i.details.hidden)i.details.open=true}));collapse.onclick=()=>groups.forEach(g=>g.items.forEach(i=>i.details.open=false));
download.onclick=()=>{const lines=['# '+data.title,'',data.origin,''];for(const g of data.groups){lines.push('## '+g.title,'',g.question,'');for(const i of g.items){lines.push('### '+i.term+' / '+i.en,'');for(const k of ['definition','distinction','example','prompt'])lines.push('**'+words[k].zh+'**：'+i[k],'');for(const id of i.refs){const n=window.ATLAS.nodes.find(n=>n.id===id);lines.push('- ['+n.name+']('+n.url+')')}lines.push('')}}for(const c of data.comparisons){lines.push('## '+c.title,'','| '+c.headers.join(' | ')+' |','| '+c.headers.map(()=> '---').join(' | ')+' |',...c.rows.map(r=>'| '+r.join(' | ')+' |'),'')}for(const r of data.route)lines.push('## '+r.title,'',r.text,'');const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/markdown;charset=utf-8'}));const a=el('a');a.href=url;a.download='alkaid-political-knowledge-tree.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
function enhanceDetail(n){const box=$('#detail .detail-inner');if(!box)return;const matched=data.groups.flatMap(g=>g.items.map(i=>({group:g,item:i}))).filter(x=>x.item.refs.includes(n.id));if(matched.length&&!box.querySelector('.tree-detail-links')){const panel=el('section','tree-detail-links');panel.dataset.noTranslate='true';panel.append(local(el('h3'),words.notes));for(const {group,item} of matched){const b=el('button','',item.term+' / '+item.en);b.onclick=()=>{input.value='';filter();tab.click();const record=groups.find(g=>g.group.id===group.id).items.find(i=>i.item===item);record.details.open=true;record.details.scrollIntoView({behavior:'smooth',block:'start'})};panel.append(b)}box.append(panel)}
 const names=window.ATLAS_PORTRAITS?.review?.nodeNames?.[n.id]||[];if(names.length&&!box.querySelector('.portrait-review')){const panel=el('details','portrait-review');panel.dataset.noTranslate='true';panel.append(local(el('summary'),words.review));for(const name of names){const item=window.ATLAS_PORTRAITS.review.people[name],p=window.ATLAS_PORTRAITS.candidates[name];panel.append(el('p','',name+' · '+item.reason),link(p.name+' · 候选来源 ↗',p.source))}box.append(panel)}
 const photos=window.ATLAS_PORTRAITS?.nodes?.[n.id]||[];const credits=box.querySelector('.image-credits');if(credits)for(const p of photos)if(p.licenseUrl&&!credits.querySelector('a[href="'+p.licenseUrl+'"]'))credits.append(local(link('',p.licenseUrl),words.license));
}
window.addEventListener('atlas:detail',e=>enhanceDetail(e.detail));
function translate(){local(tab,words.tab);input.placeholder=L(words.search);input.setAttribute('aria-label',L(words.search));local(clear,words.clear);local(expand,words.expand);local(collapse,words.collapse);local(download,words.download);local(empty,words.empty);view.querySelectorAll('.tree-definition h3,.tree-distinction h3,.tree-example h3,.tree-prompt h3').forEach(h=>{const k=h.parentElement.className.slice(5);local(h,words[k])});local(comparison.querySelector('h2'),words.comparison);local(route.querySelector('h2'),words.roadmap);filter();const n=window.ATLAS.nodes.find(n=>n.id===$('#graph .node.selected')?.dataset.id);if(n)enhanceDetail(n);document.querySelectorAll('.tree-detail-links h3').forEach(e=>local(e,words.notes));document.querySelectorAll('.portrait-review summary').forEach(e=>local(e,words.review))}
new MutationObserver(translate).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});translate();
if(location.hash.startsWith('#tree-')){tab.click();const target=document.getElementById(location.hash.slice(1));if(target)requestAnimationFrame(()=>target.scrollIntoView());}
})();
